#!/usr/bin/env bash
# ④ 2차(b) 추가 결함 재실측: S1 skip-link 평소 숨김·첫 Tab 표시(34파일 전 상태) · S2 P5 가로 스크롤·잘림 0 · S3 P6/P8/P10 도구 막대 넘침 0 · S4 P3 카드 폭·행 40
B="$HOME/.claude/skills/gstack/browse/dist/browse"
R1="file:///C:/Projects/Active/교대근무관리 시스템/시안/2026-08-31-1차HTML"
R2="file:///C:/Projects/Active/교대근무관리 시스템/시안/2026-09-02-2차HTML"
J() { "$B" js "$1" 2>/dev/null | grep -v "BEGIN\|END" | grep -v '^\s*$'; }
K() { "$B" press "$1" >/dev/null 2>&1; }
G() { "$B" goto "$1" >/dev/null 2>&1; "$B" wait --load >/dev/null 2>&1; }
"$B" viewport 1440x900 >/dev/null 2>&1
SK="()=>{const res=[];document.querySelectorAll('.state-wrapper').forEach(w=>{const a=w.querySelector('a.skip-link');if(!a)return;a.scrollIntoView({block:'center'});const r=a.getBoundingClientRect();const top=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);res.push(w.id+':'+Math.round(r.width)+'x'+Math.round(r.height)+':'+(top===a?'보임':'숨김'))});window.scrollTo(0,0);return res}"
echo "### $(date +%H:%M:%S) S1 skip-link 평소 숨김(전 상태) + 첫 Tab 표시(첫 상태)"
for p in "$R1"/03-home-1 "$R1"/03-home-2 "$R1"/05-sites-wizard-1 "$R1"/05-sites-wizard-2 "$R1"/05-sites-wizard-3 "$R1"/05-sites-wizard-4 "$R1"/08-performance-1 "$R1"/08-performance-2 "$R1"/08-performance-3 "$R1"/08-performance-4 "$R2"/00-shell-1 "$R2"/00-shell-2 "$R2"/04-sites-1 "$R2"/04-sites-2 "$R2"/06-employees-1 "$R2"/06-employees-2 "$R2"/06-employees-3 "$R2"/07-schedule-1 "$R2"/07-schedule-2 "$R2"/07-schedule-3 "$R2"/09-allowance-1 "$R2"/09-allowance-2 "$R2"/09-allowance-3 "$R2"/10-dashboard-1 "$R2"/11-operations-1 "$R2"/11-operations-2 "$R2"/11-operations-3 "$R2"/11-operations-4 "$R2"/12-access-logs-1; do
  G "$p.html"; REST=$(J "(()=>JSON.stringify(($SK)()))()"); K Tab
  FOC=$(J "(()=>{const a=document.activeElement;const r=a.getBoundingClientRect();const aw=a.closest('.app-window');const ar=aw?aw.getBoundingClientRect():{top:0,left:0};const top=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return JSON.stringify({first:a.className,w:Math.round(r.width),h:Math.round(r.height),relTop:Math.round(r.top-ar.top),relLeft:Math.round(r.left-ar.left),shown:top===a,href:a.getAttribute('href'),target:!!document.querySelector(a.getAttribute('href')||'#x')})})()")
  echo "$(basename "$p") rest=$REST tab=$FOC"
done
echo "### $(date +%H:%M:%S) S2 P5 · S3 P6/P8/P10 · S4 P3"
G "$R1/08-performance-2.html"; J "(()=>{const w=document.getElementById('state-p5');const t=w.querySelector('.compare-table');const c=t.parentElement;const rows=[...t.querySelectorAll('tbody tr')].map(r=>Math.round(r.getBoundingClientRect().height));const last=t.querySelector('tbody tr td:last-child');const lr=last.getBoundingClientRect();c.scrollLeft=9999;const lr2=last.getBoundingClientRect();return JSON.stringify({ovX:getComputedStyle(c).overflowX,cont:c.scrollWidth+'/'+c.clientWidth,scroll:c.scrollWidth>c.clientWidth,rows,lastColRightBeforeScroll:Math.round(lr.right-c.getBoundingClientRect().left),afterScrollWithin:lr2.right<=c.getBoundingClientRect().right+1,main:w.querySelector('main').scrollWidth+'/'+w.querySelector('main').clientWidth,cols:t.querySelectorAll('thead th').length})})()"
TB="(id)=>{const w=document.getElementById(id);const t=w.querySelector('.toolbar-bar');const m=w.querySelector('main');const s=w.querySelector('.filter-input[aria-label=검색]');return {id,tb:Math.round(t.getBoundingClientRect().width)+'/'+t.scrollWidth,main:m.scrollWidth+'/'+m.clientWidth,search:Math.round(s.getBoundingClientRect().width),actions:Math.round(w.querySelector('.actions-group').getBoundingClientRect().width),rows15:(()=>{const g=w.querySelector('.grid-table');if(!g)return null;const c=g.closest('[style*=overflow]')||g.parentElement;const cr=c.getBoundingClientRect();return [...g.querySelectorAll('tbody tr')].filter(r=>{const b=r.getBoundingClientRect();return b.top>=cr.top-1&&b.bottom<=cr.bottom+1}).length})()}}"
G "$R1/08-performance-3.html"; J "(()=>JSON.stringify([($TB)('state-p6')]))()"
G "$R1/08-performance-4.html"; J "(()=>JSON.stringify([($TB)('state-p8'),($TB)('state-p10')]))()"
G "$R1/08-performance-1.html"; J "(()=>{const w=document.getElementById('state-p3');const cards=[...w.querySelectorAll('.card-grid-2col > .card')].map(c=>Math.round(c.getBoundingClientRect().width));const t=w.querySelector('.nowrap-table');const wr=t.parentElement;return JSON.stringify({cards,wrap:wr.scrollWidth+'/'+wr.clientWidth,tableW:Math.round(t.getBoundingClientRect().width),rowH:[...t.querySelectorAll('tbody tr')].map(r=>Math.round(r.getBoundingClientRect().height)),cells:[...t.querySelectorAll('tbody td')].map(td=>td.textContent.trim().slice(0,14)+':'+Math.round(td.getBoundingClientRect().width)),p1cards:[...document.querySelectorAll('#state-p1 .card-grid-2col > .card')].map(c=>Math.round(c.getBoundingClientRect().width))})})()"
echo "### 끝 $(date +%H:%M:%S)"
